def main():
    dirs = (ROOT/'data/synthetic'); dirs.mkdir(parents=True,exist_ok=True)
    for j, style in enumerate(['type1','type2']):
        output = []
        for i,trip in enumerate(STORIES,1):
            inp, a, b = trip
            row = {'id':f'syn-{i:02d}', 'origin':'synthetic_hypothetical',
                   'verified_real_news': False, 'input':inp, 'output':trip[j+1].replace('\n@banki_oil', ' @banki_oil'),
                   'fact_check':'Hand-authored source/target pair; no external factual verification claimed.'}
            if not output_checks(style,row['output'])['pass']:
                raise ValueError(f'Bad synthetic {style} {i}: {output_checks(style,row["output"])}')
            output.append(row)
        write_jsonl(dirs/f'synthetic_{style}.jsonl',output)
        print(style,'synthetic:',len(output))

if __name__=='__main__':main()
